import{z as n,x as o,o as e,c as l,q as t,j as r,D as a,d as B,s as i,S as s}from"./chunks/framework.C8m1ZpeB.js";const V=JSON.parse('{"title":"网络虚拟化","description":"","frontmatter":{"title":"网络虚拟化","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/virt-network-virtualization.md","filePath":"cs/virt-network-virtualization.md","lastUpdated":1791063341000}'),D={name:"cs/virt-network-virtualization.md"};function p(d,E,h,c,C,P){const A=o("Mermaid");return e(),l("div",null,[E[2]||(E[2]=t('<h1 id="网络虚拟化" tabindex="-1">网络虚拟化 <a class="header-anchor" href="#网络虚拟化" aria-label="Permalink to &quot;网络虚拟化&quot;">​</a></h1><div class="epigraph"><p>容器的每一个包都在软件里过一遍协议栈：进出命名空间一次、过滤链若干趟、必要时再封装一层。网络虚拟化的全部设计，都是在为「每包 CPU」讨价还价。</p><footer>—— 据 Linux 网络子系统文档与数据中心 CNI 实践整理</footer></div><p><a href="/cs/virt-ns-cgroup-deep">上一课</a>把 namespace 定为视图、cgroup 定为预算，netns 是视图的网络维。本课把视图接成数据面：单个 netns 加一对 <a href="/cs/netns-veth">veth</a> 是零件，几百个容器挤在一台宿主上时，问题是<strong>组合方式</strong>——走桥还是走路由、封装还是不封装、过滤用链还是用程序。主干课讲过 VXLAN 的数据面（<a href="/cs/vxlan-overlay">VXLAN 与覆盖网</a>），本课算这笔账。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一个容器发出的包，默认路径是：容器栈 TX → veth 对端进入宿主栈 → 网桥或路由判向 → netfilter 过滤链与 <a href="/cs/netfilter-conntrack">conntrack</a> 数趟 → 可能的 VXLAN 封装 → 物理网卡。每一跳都在宿主 CPU 上，skb 分配、各链遍历、上下文切换按包计费。十万包每秒的负载，这条软件路径就是主角；万兆线速再往上，它就是天花板。缺口的形状由此明确：<strong>在「策略表达力」与「每包成本」之间选路径</strong>。</p><p><span class="marginnote">常见误区：以为容器必须「像虚拟机那样」接进二层网桥才算联网。每容器一个 /32 加宿主路由表后，全宿主是纯三层——广播域根本不存在，ARP 洪泛与 MAC 表膨胀跟着一起消失，这正是多数现代 CNI 选路由而非桥的原因。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把这条路径拆成三处可独立决策的组合点，逐处比价。</p><h3 id="三处组合决策" tabindex="-1">三处组合决策 <a class="header-anchor" href="#三处组合决策" aria-label="Permalink to &quot;三处组合决策&quot;">​</a></h3><p>第一处，桥还是路由：把容器接进二层网桥，广播与 MAC 学习跟着容器规模膨胀；改为每容器一个 /32、宿主维护路由表，全宿主变三层，收敛靠路由而非洪泛——绝大多数现代 CNI 选后者。第二处，封装与否：跨宿主若用 VXLAN，外层约五十字节头（外层以太网、IP、UDP、VXLAN 各一段），有效 MTU 从 1500 掉到 1450，且封装解封装再各付一次；若宿主间已可通路由，直接三路由到底，省掉整个隧道层。第三处，链还是程序：kube-proxy 式的 NAT 与策略靠 iptables 规则线性匹配，包在规则表里走多遍；eBPF 数据面把判向、NAT、策略压成挂在钩子上的一段程序，一次遍历完成（机制见 <a href="/cs/xdp-ebpf">XDP 与 eBPF</a>）。</p><p><span class="marginnote">数字实例：VXLAN 的外层以太网、IP、UDP 与 VXLAN 头合计约五十字节，1500 字节的包有效载荷只剩 1450；应用若不改 MTU，一个本可单包送达的载荷就得多拆一程——封装的账不止 CPU，还有每包几十字节。</span></p>',11)),(e(),r(s,null,{default:a(()=>[i(A,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20POD%5B%22%E5%AE%B9%E5%99%A8%20netns%22%5D%20--%3E%20VETH%5B%22veth%20%E5%AF%B9%E7%AB%AF%E8%BF%9B%E5%AE%BF%E4%B8%BB%22%5D%0A%20%20VETH%20--%3E%20L3%7B%22%E5%88%A4%E5%90%91%3A%20%E6%A1%A5%E6%88%96%E8%B7%AF%E7%94%B1%22%7D%0A%20%20L3%20--%3E%7C%22%E5%90%8C%E5%AE%BF%E4%B8%BB%22%7C%20PEER%5B%22%E5%AF%B9%E7%AB%AF%E5%AE%B9%E5%99%A8%20veth%22%5D%0A%20%20L3%20--%3E%7C%22%E8%B7%A8%E5%AE%BF%E4%B8%BB%22%7C%20ENC%7B%22%E5%B0%81%E8%A3%85%3F%22%7D%0A%20%20ENC%20--%3E%7C%22VXLAN%22%7C%20UDP%5B%22UDP%204789%20%E5%8A%A0%E5%A4%96%E5%B1%82%E5%A4%B4%22%5D%0A%20%20ENC%20--%3E%7C%22%E4%B8%8D%E5%B0%81%E8%A3%85%22%7C%20RT%5B%22%E5%AE%BF%E4%B8%BB%E4%B8%89%E5%B1%82%E8%BD%AC%E5%8F%91%22%5D%0A%20%20UDP%20--%3E%20NIC%5B%22%E7%89%A9%E7%90%86%E7%BD%91%E5%8D%A1%22%5D%0A%20%20RT%20--%3E%20NIC%0A%20%20VETH%20--%3E%7C%22%E6%97%81%E8%B7%AF%3A%20eBPF%20%E4%B8%80%E6%AC%A1%E9%81%8D%E5%8E%86%22%7C%20FAST%5B%22%E8%B7%B3%E8%BF%87%E9%83%A8%E5%88%86%E8%BF%87%E6%BB%A4%E9%93%BE%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>虚机侧是同一道题的另一种答案：virtio-net 让包过 KVM/QEMU 或 vhost 后端再进宿主栈（机制见 <a href="/cs/virtio">virtio</a>），成本多一层后端唤醒；VF 直通把网卡切成 SR-IOV 的虚拟功能，客户直接 DMA，hypervisor 退出数据面（<a href="/cs/sriov-passthrough">SR-IOV 与直通</a>）；<a href="/cs/dpdk-kernel-bypass">DPDK</a> 更进一步，把转发整个搬进用户态轮询。三条路在轴上的位置不同：virtio 换来迁移与快照，直通与旁路买回性能、卖掉灵活性。容器侧没有陷入可省，节约全部来自<strong>少走软件路径</strong>——少一次过滤链、少一层封装、少一次跨命名空间切换。共享内核既是容器的密度来源，也是它的网络账单：包要过的是宿主的协议栈，只是换了视角。</p>',2)),(e(),r(s,null,{default:a(()=>[i(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20VM%5B%22%E5%AE%A2%E6%9C%BA%22%5D%20--%3E%20VIRT%5B%22virtio%3A%20%E8%BD%AF%E4%BB%B6%E5%90%8E%E7%AB%AF%22%5D%0A%20%20VM%20--%3E%20VF%5B%22SR-IOV%20VF%20%E7%9B%B4%E9%80%9A%22%5D%0A%20%20VM%20--%3E%20DPDK%5B%22DPDK%20%E7%94%A8%E6%88%B7%E6%80%81%E8%BD%AE%E8%AF%A2%22%5D%0A%20%20VIRT%20--%3E%20BUY1%5B%22%E4%B9%B0%3A%20%E8%BF%81%E7%A7%BB%E4%B8%8E%E5%BF%AB%E7%85%A7%E8%83%BD%E5%8A%9B%22%5D%0A%20%20VIRT%20--%3E%20SELL1%5B%22%E5%8D%96%3A%20%E6%AF%8F%E5%8C%85%E4%B8%80%E6%AC%A1%E5%90%8E%E7%AB%AF%E5%94%A4%E9%86%92%22%5D%0A%20%20VF%20--%3E%20BUY2%5B%22%E4%B9%B0%3A%20%E8%BF%91%E5%8E%9F%E7%94%9F%20DMA%22%5D%0A%20%20VF%20--%3E%20SELL2%5B%22%E5%8D%96%3A%20%E8%BF%81%E7%A7%BB%E5%85%88%E6%8B%94%20VF%2C%20%E4%B8%8D%E5%86%8D%E5%8F%82%E4%B8%8E%E5%AE%BF%E4%B8%BB%E7%AD%96%E7%95%A5%22%5D%0A%20%20DPDK%20--%3E%20BUY3%5B%22%E4%B9%B0%3A%20%E7%BB%95%E5%BC%80%E5%86%85%E6%A0%B8%E5%8D%8F%E8%AE%AE%E6%A0%88%22%5D%0A%20%20DPDK%20--%3E%20SELL3%5B%22%E5%8D%96%3A%20%E7%8B%AC%E5%8D%A0%E8%BD%AE%E8%AF%A2%E6%A0%B8%2C%20%E7%AD%96%E7%95%A5%E8%87%AA%E7%AE%A1%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<p><span class="marginnote">直觉类比：每包 CPU 像高速收费站——包是车，过滤链与封装是一路关卡；「eBPF 一次遍历」是把五六个检查亭合并成一个窗口，「不封装」是干脆撤掉省界检查站。省 CPU 永远从少进一次软件路径开始，而不是把车造得更快。</span></p><p><span class="marginnote">服务抽象又叠一层账：ClusterIP 的 NAT 在旧式实现里是 iptables 的又一条链，包在 DNAT 上多走一遍；conntrack 表随连接数线性生长，大流量宿主上先满的常常不是带宽，是表。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CNI 插件的产品谱系，不展开 EVPN 控制面（归主干<a href="/cs/evpn">EVPN</a>），也不写 RDMA 与 RoCE 在覆盖网下的语义冲突。eBPF 数据面只钉「程序替换链」这一形态，验证器与指令集归观测课。直通的代价要背清楚：VF 绑给客户后不再参与宿主策略，迁移要先拔再插——性能与运维在同一笔交易的两端。硬件卸载（把 OVS 流表下到网卡）模糊了软件与硬件的边界，本课只承认方向：卸载的上限是硬件表容量，超表即回退软件路径。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>容器网络的成本单位是每包 CPU：进出演练栈、过滤链、封装层都按包计费。</li><li>组合三决策：路由优于桥、能不封装就不封装、eBPF 程序优于线性过滤链。</li><li>VXLAN 外层约五十字节，有效 MTU 降至 1450；跨宿主可路由时隧道层可省。</li><li>虚机侧三条路：virtio 换迁移性，SR-IOV 直通与 DPDK 旁路买回性能、卖掉灵活性。</li><li>出处：据 Linux 网络子系统文档、RFC 7348 与数据中心 CNI 实践整理。</li></ul>',6))])}const _=n(D,[["render",p]]);export{V as __pageData,_ as default};
